package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The pools on a sheet, sorted by name, and their members: people of the sheet, each in a pool at most once, with a
 * share percent. A pool's total share counts a retired member's share (a retirement date set, whatever the date) as
 * 0.00; the pool is balanced when its total is exactly 100.00. When the sheet has a pot, each member of a balanced
 * pool has a cut: the pot times their share divided by 100, rounded half to even to two decimals (0.00 for a retired
 * member); the remainder, the pot less the cuts added up, goes to the member with the largest share, the earliest
 * added on a tie, so the cuts total exactly the pot.
 */
@Service
public class Pools {

    /** The longest a pool's name may be. */
    static final int NAME_MAX = 100;

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /** A member of a pool as shown: the person, their share, whether they are retired and their cut (null: none). */
    public record Member(long personId, String name, BigDecimal share, boolean retired, BigDecimal cut) {
    }

    /** A pool as shown: its members in the order they were added, its total share and whether it is balanced. */
    public record Shown(String name, List<Member> members, BigDecimal total, boolean balanced) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ApplicationEventPublisher events;

    public Pools(PoolRepository pools, PoolMemberRepository members, PersonRepository people, SheetService sheets,
            SheetRepository sheetRows, ApplicationEventPublisher events) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.events = events;
    }

    /** The pools on the sheet, sorted by name, each with its members and figures. */
    @Transactional(readOnly = true)
    public List<Shown> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByNameAsc(sheetId);
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        BigDecimal pot = sheets.settings(sheetId).pot();
        return all.stream().map(pool -> {
            List<Member> shown = byPool.getOrDefault(pool.getId(), List.of()).stream()
                    .filter(m -> byId.containsKey(m.getPersonId()))
                    .map(m -> {
                        Person p = byId.get(m.getPersonId());
                        return new Member(p.getId(), p.getName(), m.getShare().setScale(2), p.isRetired(), null);
                    }).toList();
            BigDecimal total = shown.stream().filter(m -> !m.retired()).map(Member::share)
                    .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
            boolean balanced = total.compareTo(HUNDRED) == 0;
            return new Shown(pool.getName(), balanced && pot != null ? cut(shown, pot) : shown, total, balanced);
        }).toList();
    }

    /** The members, in the order added, each with their cut of the pot; the remainder goes to the largest share. */
    private static List<Member> cut(List<Member> shown, BigDecimal pot) {
        List<BigDecimal> cuts = new ArrayList<>();
        int largest = -1;
        for (int i = 0; i < shown.size(); i++) {
            Member m = shown.get(i);
            cuts.add(m.retired() ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(m.share()).divide(HUNDRED, 2, RoundingMode.HALF_EVEN));
            if (!m.retired() && (largest < 0 || m.share().compareTo(shown.get(largest).share()) > 0)) {
                largest = i;
            }
        }
        if (largest >= 0) {
            BigDecimal sum = cuts.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
            cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)).setScale(2));
        }
        List<Member> cut = new ArrayList<>();
        for (int i = 0; i < shown.size(); i++) {
            Member m = shown.get(i);
            cut.add(new Member(m.personId(), m.name(), m.share(), m.retired(), cuts.get(i)));
        }
        return cut;
    }

    /** Add a pool under its name, trimmed; refused when the name is blank, too long or already a pool's. */
    @Transactional
    public void add(String sheetId, String user, String text) {
        String name = text == null ? "" : text.strip();
        if (name.isEmpty()) {
            throw new PoolRefused("Enter a name for the pool.");
        }
        if (name.length() > NAME_MAX) {
            throw new PoolRefused("The pool's name is too long.");
        }
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (pools.findBySheetIdAndName(sheetId, name).isPresent()) {
            throw new PoolRefused("There is already a pool named " + name + ".");
        }
        pools.saveAndFlush(new Pool(sheetId, name));
        events.publishEvent(new PoolAdded(sheetId, user, name));
    }

    /**
     * Add a person of the sheet to the named pool with a share of two decimals, more than 0.00 and at most 100.00;
     * refused when the person is in the pool already.
     */
    @Transactional
    public void addMember(String sheetId, String user, String poolName, long personId, String text) {
        BigDecimal share = share(text);
        sheetRows.lockById(sheetId);
        Pool pool = pools.findBySheetIdAndName(sheetId, poolName == null ? "" : poolName.strip())
                .orElseThrow(() -> new PoolRefused("No such pool on this sheet."));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PoolRefused("Choose a person on this sheet."));
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
            throw new PoolRefused(person.getName() + " is in the pool already.");
        }
        members.saveAndFlush(new PoolMember(pool.getId(), person.getId(), share));
        events.publishEvent(new PoolMemberAdded(sheetId, user, pool.getName(), person.getName(), share));
    }

    private static BigDecimal share(String text) {
        String s = text == null ? "" : text.strip();
        if (!s.matches("\\d{1,3}(\\.\\d{1,2})?")) {
            throw new PoolRefused("Enter a share with up to two decimals.");
        }
        BigDecimal share = new BigDecimal(s).setScale(2);
        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
            throw new PoolRefused("A share is more than 0.00 and at most 100.00.");
        }
        return share;
    }
}
-- The pools on a sheet, each name once, and their members: people of the sheet, each in a pool at most
-- once, with a share percent (more than 0.00, at most 100.00). A person can be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL,
    CONSTRAINT pool_unique UNIQUE (sheet_id, name)
);
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
    CONSTRAINT pool_member_unique UNIQUE (pool_id, person_id)
);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { PersonWithClaims } from '../claims/claims';

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

/** A member of a pool: the person, their share (two decimals), whether they are retired and their cut of the pot. */
export interface PoolMember {
  personId: number;
  name: string;
  share: string;
  retired: boolean;
  /** Two decimals; null in an unbalanced pool or when the sheet has no pot. */
  cut: string | null;
}

/** A pool: its members, its total share (a retired member's counting 0.00) and whether that is exactly 100.00. */
export interface Pool {
  name: string;
  members: PoolMember[];
  total: string;
  balanced: boolean;
}

/** What is typed into a pool's member form, and why its last add was refused. */
interface Draft {
  personId: string;
  share: string;
  error: string;
}

const EMPTY: Draft = { personId: '', share: '', error: '' };

// The sheet's pools, sorted by name, each with its members and their shares, its total share and whether it is
// balanced, and each member's cut of the sheet's pot (none unless the pool is balanced and there is a pot); the form that adds a pool, and on each pool's row the form that adds a person to it with a share.
// A person can be in several pools, each at most once.
@Component({
  selector: 'app-pools',
  template: `
    <section aria-label="Pools">
      <h2>Pools</h2>
      <ul>
        @for (p of pools(); track p.name) {
          <li [attr.data-testid]="'pool-row-' + p.name">
            <span data-testid="pool-name">{{ p.name }}</span>
            <span>Total share <span data-testid="pool-total-share">{{ p.total }}</span></span>
            <span>Balanced <span data-testid="pool-balanced">{{ p.balanced ? 'yes' : 'no' }}</span></span>
            <ul>
              @for (m of p.members; track m.personId) {
                <li [attr.data-testid]="'pool-member-' + p.name + '-' + m.personId">
                  <span data-testid="pool-member-name">{{ m.name }}</span>
                  <span>Share <span data-testid="pool-share">{{ m.share }}</span></span>
                  <span>Cut <span data-testid="pool-cut">{{ m.cut ?? '' }}</span></span>
                  @if (m.retired) {
                    <span>(retired)</span>
                  }
                </li>
              }
            </ul>
            <form (submit)="addMember($event, p.name)" [attr.aria-label]="'Add member to pool ' + p.name">
              <label [for]="'pool-member-select-' + p.name">Person</label>
              <select
                [id]="'pool-member-select-' + p.name"
                data-testid="pool-member-select"
                [value]="draft(p.name).personId"
                (change)="edit(p.name, { personId: value($event) })"
              >
                <option value="" [selected]="draft(p.name).personId === ''">Choose a person</option>
                @for (person of people(); track person.id) {
                  <option [value]="'' + person.id" [selected]="draft(p.name).personId === '' + person.id">
                    {{ person.name }}
                  </option>
                }
              </select>
              <label [for]="'pool-member-share-' + p.name">Share %</label>
              <input
                [id]="'pool-member-share-' + p.name"
                data-testid="pool-member-share"
                inputmode="decimal"
                [value]="draft(p.name).share"
                (input)="edit(p.name, { share: value($event) })"
              />
              <button type="submit" data-testid="pool-member-add">Add member</button>
              @if (draft(p.name).error) {
                <p role="alert" data-testid="pool-error">{{ draft(p.name).error }}</p>
              }
            </form>
          </li>
        }
      </ul>
      <form (submit)="add($event)" aria-label="Add pool">
        <label for="pool-form-name">Name</label>
        <input
          id="pool-form-name"
          data-testid="pool-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set('')"
        />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error()) {
          <p role="alert" data-testid="pool-form-error">{{ error() }}</p>
        }
      </form>
    </section>
  `,
})
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Everyone on the sheet, retired people included: the choices for a member, re-read as they change. */
  readonly people = input.required<PersonWithClaims[]>();

  protected readonly pools = signal<Pool[]>([]);
  protected readonly name = signal('');
  protected readonly error = signal('');
  protected readonly drafts = signal<Record<string, Draft>>({});
  /** Each answer is numbered: one older than the last shown is dropped. */
  private asked = 0;
  private shown = 0;
  /** A submit still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.pools.set([]);
      this.name.set('');
      this.error.set('');
      this.drafts.set({});
      if (sheet) void this.reload(sheet);
    });
    // a member's retirement changes the pool's total: re-read the pools whenever the people change
    effect(() => {
      this.people();
      const sheet = this.session.sheet();
      if (sheet) void this.reload(sheet);
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected draft(pool: string): Draft {
    return this.drafts()[pool] ?? EMPTY;
  }

  protected edit(pool: string, change: Partial<Draft>): void {
    this.drafts.update((all) => ({ ...all, [pool]: { ...(all[pool] ?? EMPTY), ...change, error: '' } }));
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    const name = this.name().trim();
    if (name === '') {
      this.error.set('Enter a name for the pool.');
      return;
    }
    this.busy = true;
    try {
      const refusal = await this.post('', { name });
      if (refusal) this.error.set(refusal);
      else this.name.set('');
    } finally {
      this.busy = false;
    }
  }

  protected async addMember(e: Event, pool: string): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    const draft = this.draft(pool);
    this.edit(pool, {});
    const share = draft.share.trim();
    let refusal = '';
    if (draft.personId === '') {
      refusal = 'Choose a person.';
    } else if (!SHARE.test(share) || Number(share) <= 0 || Number(share) > 100) {
      refusal = 'Enter a share with up to two decimals, more than 0.00 and at most 100.00.';
    } else {
      this.busy = true;
      try {
        refusal = await this.post('/members', { pool, personId: Number(draft.personId), share });
      } finally {
        this.busy = false;
      }
    }
    if (refusal) this.drafts.update((all) => ({ ...all, [pool]: { ...(all[pool] ?? EMPTY), error: refusal } }));
    else this.drafts.update((all) => ({ ...all, [pool]: EMPTY }));
  }

  /** Post a change: '' once made (the pools shown as they now stand), else why it was refused. */
  private async post(path: string, body: object): Promise<string> {
    const sheet = this.session.sheet();
    if (!sheet) return 'Load a sheet first.';
    const headers = { 'X-User': this.session.user() ?? '' };
    const n = ++this.asked;
    try {
      const pools = await firstValueFrom(
        this.http.post<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools${path}`, body, { headers }),
      );
      this.show(sheet, n, pools);
      return '';
    } catch (err) {
      const answer = err instanceof HttpErrorResponse ? err : null;
      return answer?.error?.message ?? 'Could not save the pool.';
    }
  }

  private async reload(sheet: string): Promise<void> {
    const n = ++this.asked;
    const pools = await firstValueFrom(this.http.get<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`));
    this.show(sheet, n, pools);
  }

  private show(sheet: string, n: number, pools: Pool[]): void {
    if (this.session.sheet() !== sheet || n < this.shown) return;
    this.shown = n;
    this.pools.set(pools);
  }
}
